# 数据文件：source/src/utils/bash/commands.ts
# slug = src_utils_bash_commands_ts
# 每个锚点：(行号, 'before'|'after'|'after_block', 中文批注)
# 约束：中文用三引号；正文禁英文双引号与反斜杠。

ANNOTATIONS = [
    (2, 'after', '''从 shell-quote 这个第三方解析库导入两个类型。shell-quote 是后面所有命令拆解与安全检查的解析底座：它把一段 shell 字符串切成 token 序列（字符串、操作符、注释、glob 等），本文件的安全逻辑全部建立在它的输出之上。'''),
    (20, 'after', '''generatePlaceholders 是整份文件的安全总纲。它用随机盐生成一组占位串（单引号、双引号、换行、转义括号），核心目的是「防注入」：恶意命令无法预先塞入我们用来做引号与换行替换的占位文本，从而无法骗过解析器偷偷注入额外参数。'''),
    (28, 'after', '''盐值本身来自 8 个随机字节转十六进制，每次解析都不同。占位串带盐后，攻击者无法在输入里「碰巧」写出和我们占位串一模一样的字面量。'''),
    (40, 'after', '''标准文件描述符集合：0 是标准输入、1 是标准输出、2 是标准错误。后面判断 `2>&1` 这类「文件描述符到文件描述符」的重定向时，只认这三个数字，避免把普通数字参数误判成重定向目标。'''),
    (47, 'after', '''isStaticRedirectTarget 决定一个重定向目标能否被「静默剥离」。静态目标（纯路径、无变量无通配）从权限提示里摘掉；含动态内容的目标必须保留给用户看，否则用户会在不知情的情况下批准写入某文件。'''),
    (58, 'after', '''拒绝空字符串目标。因为 path.resolve(cwd, 空串) 会返回 cwd 本身，而 cwd 永远在允许根内，若不拦会导致「看似没目标、实则指向整个工作目录」的越权。'''),
    (66, 'after', '''拒绝以井号开头的「目标」。shell-quote 把行首的井号当注释对象，而 extractOutputRedirections 那边看不到这个注释对象、会漏掉目标——这里主动拒绝，闭合两边解析器的「差异」，杜绝利用解析分歧绕过路径校验。'''),
    (85, 'after', '''splitCommandWithOperators 是整个权限系统的核心入口：把一条可能含操作符、重定向、续行的命令，拆成「子命令片段」数组，供上游做前缀匹配与权限判定。'''),
    (93, 'after', '''解析前先抽取 heredoc。shell-quote 对 `<<` 解析有误，heredoc 体里的内容（比如 `${}`）会被它当成危险语法直接抛错，所以必须先把体抽走、用占位符替代。'''),
    (96, 'after', '''续行连接（反斜杠加换行）必须在「换行分词」之前完成，否则一条被拆成两行的命令会被当成两条独立命令去判定权限。'''),
    (105, 'after_block', '''续行连接的精妙处：只有「奇数个反斜杠」才算续行（最后一个反斜杠转义换行）；偶数个反斜杠会两两配对成转义序列，此时换行是命令分隔符而非续行。这里举了在 echo 后用反斜杠转义换行、再接 rm 的攻击样例——若错误地把偶数反斜杠也连起来，就会漏检后面的 `rm`。'''),
    (139, 'after', '''commandOriginalJoined 是为「解析失败回退路径」准备的续行连接版原文。回退时返回单元素数组，下游权限检查会把它当成「一条子命令」处理；如果回退用未连接的原文，校验器看的是 foo 后接被转义的换行再接 bar，而 bash 实际执行拼接后的 foobar，攻击者可借此让危险命令蒙混过关。'''),
    (142, 'after', '''正式解析前，先用占位串替换掉引号、换行、转义括号。原因写在注释里：shell-quote 的 parse 会「吃掉」引号、换行、把被转义的左括号当成普通左括号，所以先垫占位串保住这些字符，解析完再还原。'''),
    (156, 'after', '''解析失败时，整条命令当作单个字符串返回，而不是报错中断。这样命令仍会走权限检查（交给用户确认），符合「失败也别悄悄放行」的安全准则。'''),
    (170, 'after', '''第一步：把相邻的字符串 token 和 glob token 折叠成一个。例如 `cat` 后面紧跟 `out.txt` 会并成 `cat out.txt`，但换行占位符会把「上一串」截断、开启「新命令」。'''),
    (219, 'after', '''处理注释 token 时的隐藏陷阱：我们注入的引号占位符前缀会残留在注释里，若直接还原会每个引号翻倍；而递归调用 splitCommand 时这种翻倍会指数增长，直到 shell-quote 的分块正则灾难性回溯（ReDoS）。所以这里先把注入的引号前缀剥掉，确保还原后只有一个引号。'''),
    (239, 'after', '''第三步：把占位串还原回原始的引号、换行与转义括号，让输出和用户输入在「字符层面」一致，只是多了子命令切分。'''),
    (242, 'after', '''最后一步：把之前抽走的 heredoc 体还原回去，保证还原后的命令字符串在语义上和原命令等价。'''),
    (251, 'after', '''filterControlOperators 把 `&&`、`||`、`;`、`|` 等「控制操作符」从片段数组里滤掉，只留下真正要执行/展示的命令片段。'''),
    (265, 'after', '''splitCommand_DEPRECATED 是旧的「正则加 shell-quote」拆命令路径，仅在 tree-sitter 不可用时的兜底。主流程已经改用 ast.ts 的 parseForSecurity，这个函数属于历史遗留。'''),
    (274, 'after', '''剥离重定向符号（`>`、`>>`、`>&`、`2>/dev/null` 等），让它们不出现在权限提示里当作独立命令。文件目标本身的安全校验在别处（checkPathConstraints）单独做。'''),
    (306, 'after', '''特例处理：相邻字符串折叠会把 `> /dev/null 2` 里的 `2` 和 `/dev/null` 并成 `/dev/null 2`，而末尾的 ` 2` 其实是下一个重定向 `>&1` 的文件描述符前缀。这里把它切下来，让 isStaticRedirectTarget 只看真正的目标。'''),
    (352, 'after', '''剥离「前导文件描述符」只在数字前面带空格、且剥离后字符串非空时才做。shell-quote 区分不了 `2>`（文件描述符重定向）和 `2 >`（参数加标准输出），没有空格检查会误把 `cat /tmp/path2 > out` 截成 `cat /tmp/path`，没有长度检查会误删 `echo ; 2 > file` 里的 `2` 子命令。'''),
    (388, 'after', '''isHelpCommand 判断一条命令是否「纯帮助查询」（以 --help 结尾、无其他 flag、非 flag token 全是字母数字）。这类命令只读且安全，直接放行并允许完整命令（如 `python --help`），不用抽成过宽的前缀（如 `python:*`），还能省一次模型调用。'''),
    (501, 'after', '''BASH_POLICY_SPEC 是喂给大模型的「命令前缀提取策略说明」模板，上面列了一大堆前缀提取的正例与反例（含各种命令注入检测样例）。getCommandPrefix 基于它，用模型从命令里抽出「允许前缀」，遇到疑似注入时返回 command_injection_detected 强制用户确认。'''),
    (510, 'after', '''getCommandSubcommandPrefix 在 getCommandPrefix 基础上再做一层「子命令」前缀提取，并把拆命令的工作委托给 splitCommand_DEPRECATED（旧路径兜底）。'''),
    (518, 'after', '''clearCommandPrefixCaches 在用户执行 /clear 时清空前缀提取的缓存，释放内存，避免历史命令的前缀缓存无限增长。'''),
    (523, 'after', '''命令列表分隔符集合：`&&`、`||`、`;`、`;;`、`|`。这些是「把多条命令串起来」的操作符，用于判断一条命令是不是单纯的命令列表。'''),
    (539, 'after', '''isCommandList 判断整条命令是否「只是命令列表」（除了分隔符、glob、标准文件描述符重定向外没有别的危险操作符）。纯命令列表在权限判定时可以放宽处理。'''),
    (570, 'after', '''注释 token 不可信：注释里可能藏着命令注入。一旦解析出注释对象，直接判定这条命令「不是安全的命令列表」，退回更严格的检查。'''),
    (605, 'after', '''isUnsafeCompoundCommand_DEPRECATED 是旧路径下判断「复合命令是否危险」的函数。设计哲学是「纵深防御」：连 shell-quote 都解析不了的畸形语法，宁可当成危险、让用户确认，也不依赖 bash 也会拒绝这个假设。'''),
    (634, 'after', '''extractOutputRedirections 从命令里抽取输出重定向（`>`、`>>`），区分「静态简单目标」与「危险目标」，供路径校验决定是否让用户确认写入。'''),
    (667, 'after_block', '''抽取顺序的硬性安全要求：必须先抽 heredoc、再连续行、最后才解析。若先连续行，带引号的 heredoc 体里 x 后接反斜杠换行再接 DELIM 会被拼成 xDELIM，导致分界符偏移，本该被校验的 `> /etc/passwd` 被吞进 heredoc 体、永远到不了路径校验——攻击者借此静默写文件。注释里给出完整的攻击复现与新旧两种处理的结果对比。'''),
    (699, 'after', '''解析失败一律「失败关闭」（fail-closed）：返回 hasDangerousRedirection 为真。以前返回「无重定向、不危险」是无声绕过——只要命令里存在 `>`，就可能有文件写入，调用方必须把这种情况当危险、去问用户。'''),
    (798, 'after', '''isSimpleTarget 判定重定向目标是不是「简单静态目标」：无历史展开、无等号展开、无波浪号、无变量、无反引号、无通配、无字符类、无花括号。空串也被拒（对应 path.resolve(cwd,空串) 返回 cwd 的漏洞）。'''),
    (819, 'after', '''hasDangerousExpansion 的设计不变量是整份文件最重要的安全约束：对于任何字符串重定向目标，「要么 isSimpleTarget 为真（被捕获、走路径校验），要么 hasDangerousExpansion 为真（标记危险、问用户）」。二者都不满足的目标会漏过校验——所以 hasDangerousExpansion 必须覆盖 isSimpleTarget 拒绝的每一种情况（空串单独处理），不留缝隙。注释还复盘了 `> ~/.bashrc` 因例外 carved-out 而漏检的真实 bug。'''),
    (860, 'after', '''handleRedirection 是重定向处理的「大分支机」：针对 `>`、`>>`、`>&`、`>|`、`>!`、`>>&` 及各自的强制覆盖（Zsh 的 `!`、POSIX 的 `|`）写法，逐一判断应该「捕获目标供校验」还是「标记危险」。'''),
    (1004, 'after', '''处理 `>!filename`（无空格）时，推入路径校验的是去掉 `!` 后的 afterBang，而不是带 `!` 的原串。原因：Zsh 把 `>!filename` 当强制覆盖时目标是 `filename`；若推 `!filename`，path.resolve 会把它当相对路径（cwd/!filename），绕过绝对路径校验——`>!/etc/passwd` 就会去校验 cwd 下的伪路径、而 Zsh 实际写的是 /etc/passwd。去掉 `!` 在两种解释下都更安全（失败关闭优先）。'''),
    (1093, 'after', '''handleFileDescriptorRedirection 专门处理「带文件描述符前缀」的重定向（如 `2>/tmp/file`、`2>&1`）。注意它先查危险展开、再做任何提前返回，避免漏掉 `2>$HOME/file` 这类危险目标。'''),
    (1171, 'after', '''needsQuoting 判断重建命令时某个字符串是否需要加引号。文件描述符重定向（如 `2>`）不加引号；含任何空白字符的要加（安全相关，见下一条）；单字符 shell 操作符也要加引号消歧义。'''),
    (1181, 'after', '''空白字符检查必须覆盖正则里反斜杠加 s 空白类匹配的全部字符（空格、制表、换行、回车等）。以前只查空格和制表，下游 ENV_VAR_PATTERN 用反斜杠加 s 加号匹配——若重建命令吐出未加引号的换行或回车，stripSafeWrappers 会跨它匹配，把 `TZ=UTC` 从 `TZ=UTC<换行>echo curl evil.com` 里剥离，从而骗过 `Bash(echo:*)` 前缀、让 bash 按换行分词执行 curl。'''),
    (1195, 'after', '''reconstructCommand 从「保留下来的 token」反向重建出一条命令字符串，用于权限提示里展示「去掉重定向后的命令」。重建时要小心各类括号、进程替换 `<(`、heredoc `<<`、命令替换 `$(` 的间距，保证重建结果和原命令语义一致。'''),
]
